import heapq

class Solution:
    def minStoneSum(self, piles: list[int], k: int) -> int:
        pq = [-x for x in piles]
        heapq.heapify(pq)

        for _ in range(k):
            top = -heapq.heappop(pq)
            reduced = top - top // 2
            heapq.heappush(pq, -reduced)

        return -sum(pq)

class Solution {
public:
    int minStoneSum(vector<int>& piles, int k) {
        priority_queue<int> pq(piles.begin(), piles.end());
        for (int i = 0; i < k; i++) {
            int top = pq.top();
            pq.pop();
            pq.push(top - top / 2);
        }
        int total = 0;
        while (!pq.empty()) {
            total += pq.top();
            pq.pop();
        }
        return total;
    }
};

class Solution {
    public int minStoneSum(int[] piles, int k) {
        java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>((a, b) -> Integer.compare(b, a));
        int total = 0;
        for (int p : piles) {
            pq.offer(p);
            total += p;
        }
        for (int i = 0; i < k; i++) {
            int top = pq.poll();
            int remove = top / 2;
            total -= remove;
            pq.offer(top - remove);
        }
        return total;
    }
}

var minStoneSum = function(piles, k) {
  // Count bucket frequency approach or max heap simulation
  const maxVal = Math.max(...piles);
  const count = new Array(maxVal + 1).fill(0);
  let total = 0;
  for (const p of piles) {
    count[p]++;
    total += p;
  }
  let curr = maxVal;
  while (k > 0 && curr > 0) {
    if (count[curr] === 0) {
      curr--;
      continue;
    }
    const take = Math.min(k, count[curr]);
    const remove = Math.floor(curr / 2);
    total -= take * remove;
    count[curr] -= take;
    count[curr - remove] += take;
    k -= take;
  }
  return total;
};
